Here's your water tracker: tap **+** after each glass, and it shows your progress toward 8.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: sans-serif; text-align: center; padding: 24px; }
  h1 { font-size: 22px; margin-bottom: 4px; }
  #count { font-size: 48px; margin: 12px 0; }
  #glasses { font-size: 32px; letter-spacing: 6px; min-height: 44px; }
  #bar { height: 12px; background: #ddd; border-radius: 6px; margin: 16px auto; max-width: 300px; }
  #fill { height: 12px; width: 0; background: #2a8fd8; border-radius: 6px; }
  button { font-size: 22px; padding: 8px 22px; margin: 4px; border-radius: 8px; border: 1px solid #888; cursor: pointer; }
  #msg { margin-top: 12px; min-height: 22px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="glasses"></div>
  <div id="bar"><div id="fill"></div></div>
  <button onclick="change(-1)">−</button>
  <button onclick="change(1)">+</button>
  <div><button onclick="reset()" style="font-size:14px">Start over</button></div>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toDateString();
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key)) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, n); } catch (e) {} }

  function draw() {
    document.getElementById("date").textContent = today;
    document.getElementById("count").textContent = n + " / " + GOAL;
    var g = "";
    for (var i = 0; i < Math.max(n, GOAL); i++) g += i < n ? "💧" : "○";
    document.getElementById("glasses").textContent = g;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
  }

  function change(d) { n = Math.max(0, n + d); save(); draw(); }
  function reset() { n = 0; save(); draw(); }
  draw();
</script>
</body>
</html>
```

Your count is saved for today if the app allows it, and starts fresh tomorrow.
